public class CapacityEstimator {
    // Estimating daily storage in bytes
    public long estimateDailyStorage(long rps, int avgRecordSizeBytes, double indexOverhead) {
        long secondsInDay = 86400;
        long totalRecords = rps * secondsInDay;
        return (long) (totalRecords * avgRecordSizeBytes * (1 + indexOverhead));
    }
}
